/* ============================================================
   GRAVITY BREAK — level data & compiler
   Levels are declared as simple geometry; compile() expands
   them into a tile grid + entity lists. Pure data, no DOM —
   this file is also loaded by Node (test/validate.js).
   ============================================================ */
(function (root) {
  'use strict';

  var T = 32; // tile size in px

  /* Level object format:
     w           : width in tiles (h is always 17)
     start,goal  : [tx,ty] tiles (entity baseline tile)
     solid       : [x, y, w, h] rects of solid tiles
     spikes      : [x, y, n, dir]  dir 'up' (floor) | 'down' (ceiling)
     lasers      : [x, y, len, axis('v'|'h'), phase(0|1)]
     movers      : [tx, ty, axis, len(px), speed(px/s)]
     shards      : [tx, ty]
     checkpoints : [tx, ty]                                     */

  var LEVELS = [
    {
      name: 'FIRST CONTACT', accent: '#00e5ff', w: 64,
      start: [2, 14], goal: [58, 14],
      solid: [
        [0, 15, 14, 2], [18, 15, 14, 2], [37, 15, 27, 2],
        [25, 12, 3, 1], [46, 13, 4, 1], [51, 11, 3, 1]
      ],
      spikes: [],
      lasers: [],
      movers: [],
      shards: [[4, 13], [14, 11], [21, 12], [26, 10], [34, 11], [47, 11], [52, 9], [55, 13]],
      checkpoints: [[42, 14]]
    },
    {
      name: 'UPSIDE', accent: '#b26bff', w: 64,
      start: [2, 14], goal: [60, 14],
      solid: [
        [0, 0, 64, 1],            // ceiling
        [0, 15, 64, 2],           // floor
        [16, 4, 2, 11],           // wall 1 (must go over via ceiling)
        [38, 5, 2, 10]            // wall 2
      ],
      spikes: [
        [26, 14, 6, 'up'], [26, 1, 6, 'down'],   // kill both -> drop between walls
        [46, 14, 5, 'up']                        // floor trap -> ride ceiling above
      ],
      lasers: [],
      movers: [],
      shards: [[8, 13], [12, 2], [20, 2], [30, 13], [35, 3], [43, 2], [49, 2], [55, 13]],
      checkpoints: [[22, 14], [44, 14]]
    },
    {
      name: 'SPIKE ALLEY', accent: '#ff2d78', w: 72,
      start: [2, 14], goal: [69, 14],
      solid: [
        [0, 15, 20, 2], [25, 15, 15, 2], [45, 15, 27, 2],
        [21, 13, 4, 1], [41, 12, 3, 1],
        [50, 12, 8, 1],             // bridge over long spike field
        [60, 0, 10, 1]              // partial ceiling
      ],
      spikes: [
        [30, 14, 3, 'up'], [35, 14, 2, 'up'],
        [50, 14, 8, 'up'],
        [64, 1, 2, 'down']
      ],
      lasers: [],
      movers: [],
      shards: [[10, 13], [15, 11], [22, 11], [28, 12], [33, 11], [42, 10], [47, 13], [53, 10], [61, 2], [66, 12]],
      checkpoints: [[27, 14], [58, 14]]
    },
    {
      name: 'LASER GRID', accent: '#ffe14d', w: 72,
      start: [2, 14], goal: [68, 14],
      solid: [
        [0, 15, 72, 2]
      ],
      spikes: [],
      lasers: [
        [10, 7, 8, 'v', 0], [11, 7, 8, 'v', 0],
        [18, 7, 8, 'v', 1], [19, 7, 8, 'v', 1],
        [26, 7, 8, 'v', 0], [27, 7, 8, 'v', 0],
        [34, 7, 8, 'v', 1], [35, 7, 8, 'v', 1],
        [42, 7, 8, 'v', 0], [43, 7, 8, 'v', 0],
        [50, 7, 8, 'v', 1], [51, 7, 8, 'v', 1],
        [58, 12, 8, 'h', 0]
      ],
      movers: [],
      shards: [[6, 13], [14, 13], [22, 12], [30, 13], [38, 12], [46, 13], [55, 13], [62, 14]],
      checkpoints: [[36, 14]]
    },
    {
      name: 'THE LIFT', accent: '#ffb347', w: 72,
      start: [2, 14], goal: [69, 14],
      solid: [
        [0, 15, 16, 2], [32, 15, 9, 2], [57, 15, 15, 2]
      ],
      spikes: [
        [34, 14, 3, 'up']
      ],
      lasers: [],
      movers: [
        [17, 13, 'x', 12 * T, 105],
        [44, 12, 'x', 9 * T, 120]
      ],
      shards: [[7, 13], [22, 10], [31, 11], [37, 12], [47, 9], [54, 11], [63, 13], [70, 13]],
      checkpoints: [[38, 14], [59, 14]]
    },
    {
      name: 'MIRROR RUN', accent: '#7c4dff', w: 80,
      start: [2, 14], goal: [77, 14],
      solid: [
        [0, 0, 80, 1],
        [0, 15, 80, 2],
        [14, 12, 2, 3],            // step wall (jumpable)
        [42, 4, 2, 11],            // tall wall -> ceiling route
        [70, 12, 2, 3]             // step wall
      ],
      spikes: [
        [24, 14, 8, 'up'], [24, 1, 8, 'down'],   // zone 1 -> mover across
        [52, 14, 6, 'up'], [52, 1, 6, 'down']    // zone 2 -> mover across
      ],
      lasers: [],
      movers: [
        [23, 12, 'x', 11 * T, 150],
        [51, 12, 'x', 8 * T, 150]
      ],
      shards: [[8, 13], [17, 11], [28, 10], [38, 13], [45, 2], [55, 10], [63, 11], [67, 13], [73, 11], [80, 13]],
      checkpoints: [[20, 14], [36, 14], [66, 14], [75, 14]]
    },
    {
      name: 'THE GAUNTLET', accent: '#ff5c39', w: 90,
      start: [2, 14], goal: [87, 14],
      solid: [
        [0, 15, 14, 2], [20, 15, 12, 2], [46, 15, 14, 2], [60, 15, 30, 2],
        [32, 13, 6, 1],
        [60, 0, 20, 1]             // ceiling stretch
      ],
      spikes: [
        [10, 14, 3, 'up'],
        [50, 14, 3, 'up'],
        [68, 14, 6, 'up'],
        [62, 1, 4, 'down']
      ],
      lasers: [
        [26, 7, 8, 'v', 0], [27, 7, 8, 'v', 0],
        [74, 7, 8, 'v', 1], [75, 7, 8, 'v', 1]
      ],
      movers: [
        [13, 13, 'x', 6 * T, 130],
        [32, 13, 'x', 9 * T, 140]
      ],
      shards: [[7, 12], [16, 10], [23, 13], [29, 12], [36, 10], [43, 12], [51, 10], [57, 13], [62, 13], [70, 2], [78, 13], [84, 13]],
      checkpoints: [[21, 14], [47, 14], [65, 14]]
    },
    {
      name: 'GRAVITY BREAK', accent: '#00ffd0', w: 100,
      start: [2, 14], goal: [96, 14],
      solid: [
        [0, 15, 10, 2], [16, 15, 16, 2], [36, 15, 20, 2],
        [56, 15, 20, 2], [80, 15, 20, 2],
        [36, 0, 20, 1], [80, 0, 20, 1],   // ceiling sections
        [86, 4, 2, 11],                    // final tall wall
        [43, 12, 8, 1]                     // bridge over mirror zone (static)
      ],
      spikes: [
        [20, 14, 4, 'up'],
        [44, 14, 6, 'up'], [44, 1, 6, 'down'],
        [70, 14, 3, 'up'],
        [91, 14, 4, 'up'], [91, 1, 4, 'down']
      ],
      lasers: [
        [26, 7, 8, 'v', 0], [27, 7, 8, 'v', 0],
        [64, 7, 8, 'v', 1], [65, 7, 8, 'v', 1]
      ],
      movers: [
        [10, 13, 'x', 5 * T, 130]
      ],
      shards: [[5, 13], [13, 10], [21, 11], [24, 13], [30, 12], [34, 11], [40, 13], [47, 10], [52, 10], [60, 13], [68, 12], [74, 12], [83, 2], [90, 12], [95, 2], [97, 13]],
      checkpoints: [[17, 14], [57, 14], [82, 14]]
    }
  ];

  /* ---------- Compiler ---------- */
  function compile(def, index) {
    var h = 17, w = def.w;
    var grid = new Uint8Array(w * h);          // 0 empty 1 solid 2 spike-up 3 spike-down
    var inBounds = function (x, y) { return x >= 0 && y >= 0 && x < w && y < h; };

    // solid rects
    def.solid.forEach(function (r) {
      for (var y = r[1]; y < r[1] + r[3]; y++)
        for (var x = r[0]; x < r[0] + r[2]; x++)
          if (inBounds(x, y)) grid[y * w + x] = 1;
    });

    // spikes
    var spikes = [];
    def.spikes.forEach(function (s) {
      for (var i = 0; i < s[2]; i++) {
        var x = s[0] + i, y = s[1];
        if (!inBounds(x, y)) continue;
        // don't overwrite solid
        if (grid[y * w + x] !== 1) grid[y * w + x] = (s[3] === 'up') ? 2 : 3;
        spikes.push({ tx: x, ty: y, dir: s[3] });
      }
    });

    // lasers
    var lasers = def.lasers.map(function (l) {
      return { tx: l[0], ty: l[1], len: l[2], axis: l[3], phase: l[4] };
    });

    // movers
    var movers = def.movers.map(function (m, i) {
      return {
        id: i, tx: m[0], ty: m[1],
        axis: m[2], travel: m[3], speed: m[4],
        x: m[0] * T, y: m[1] * T,
        w: 3 * T, h: 14, dir: 1, u: 0, dx: 0, dy: 0
      };
    });

    var shards = def.shards.map(function (s, i) {
      return { id: i, x: s[0] * T + T / 2, y: s[1] * T + T / 2, tx: s[0], ty: s[1], taken: false };
    });

    var checkpoints = def.checkpoints.map(function (c, i) {
      return { id: i, x: c[0] * T + T / 2, y: c[1] * T, tx: c[0], ty: c[1], active: false };
    });

    return {
      index: index, def: def,
      name: def.name, accent: def.accent,
      w: w, h: h,
      grid: grid,
      spikes: spikes, lasers: lasers, movers: movers,
      shards: shards, checkpoints: checkpoints,
      start: { tx: def.start[0], ty: def.start[1] },
      goal: { tx: def.goal[0], ty: def.goal[1] }
    };
  }

  var api = {
    TILE: T,
    LEVEL_COUNT: LEVELS.length,
    LEVELS: LEVELS,
    compile: compile
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.GBLevels = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);

/* ============================================================
   GRAVITY BREAK — audio engine
   All SFX are synthesized with WebAudio (no assets needed).
   Includes a lightweight procedurally-scheduled music loop.
   ============================================================ */
(function (root) {
  'use strict';

  function AudioEngine() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.enabled = true;
    this.musicOn = true;
    this._musicTimer = null;
    this._step = 0;
    this._nextTime = 0;
    this.bpm = 116;
  }

  AudioEngine.prototype._ensure = function () {
    if (this.ctx) return true;
    try {
      var AC = root.AudioContext || root.webkitAudioContext;
      if (!AC) return false;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.55;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.5;
      this.musicGain.connect(this.master);
      return true;
    } catch (e) { return false; }
  };

  AudioEngine.prototype.resume = function () {
    if (this._ensure() && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(function () {});
    }
  };

  AudioEngine.prototype.setSound = function (on) {
    this.enabled = on;
    if (this.master) this.master.gain.value = on ? 0.55 : 0;
  };

  /* Basic tone helper */
  AudioEngine.prototype._tone = function (opt) {
    if (!this._ensure() || !this.enabled) return;
    var t0 = this.ctx.currentTime + (opt.delay || 0);
    var osc = this.ctx.createOscillator();
    var g = this.ctx.createGain();
    osc.type = opt.type || 'square';
    osc.frequency.setValueAtTime(opt.f0 || 440, t0);
    if (opt.f1) osc.frequency.exponentialRampToValueAtTime(Math.max(20, opt.f1), t0 + (opt.slide || 0.1));
    var v = opt.vol || 0.2;
    var a = opt.attack || 0.005;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(v, t0 + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + (opt.dur || 0.15));
    var dest = opt.music ? this.musicGain : this.master;
    osc.connect(g); g.connect(dest);
    osc.start(t0); osc.stop(t0 + (opt.dur || 0.15) + 0.05);
  };

  AudioEngine.prototype._noise = function (opt) {
    if (!this._ensure() || !this.enabled) return;
    var t0 = this.ctx.currentTime + (opt.delay || 0);
    var len = Math.max(1, Math.floor(this.ctx.sampleRate * (opt.dur || 0.2)));
    var buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    var d = buf.getChannelData(0);
    for (var i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    var src = this.ctx.createBufferSource();
    src.buffer = buf;
    var g = this.ctx.createGain();
    g.gain.value = opt.vol || 0.2;
    var f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = opt.freq || 1200;
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t0);
  };

  /* ----- SFX ----- */
  AudioEngine.prototype.jump = function () {
    this._tone({ type: 'square', f0: 260, f1: 620, slide: 0.12, dur: 0.16, vol: 0.14 });
  };
  AudioEngine.prototype.flip = function () {
    this._tone({ type: 'sawtooth', f0: 700, f1: 180, slide: 0.16, dur: 0.2, vol: 0.16 });
    this._tone({ type: 'sine', f0: 140, f1: 560, slide: 0.16, dur: 0.2, vol: 0.1, delay: 0.02 });
  };
  AudioEngine.prototype.land = function () {
    this._noise({ dur: 0.06, vol: 0.10, freq: 500 });
  };
  AudioEngine.prototype.collect = function () {
    this._tone({ type: 'sine', f0: 720, dur: 0.09, vol: 0.16 });
    this._tone({ type: 'sine', f0: 1080, dur: 0.14, vol: 0.16, delay: 0.07 });
  };
  AudioEngine.prototype.checkpoint = function () {
    this._tone({ type: 'triangle', f0: 520, dur: 0.12, vol: 0.16 });
    this._tone({ type: 'triangle', f0: 660, dur: 0.12, vol: 0.16, delay: 0.09 });
    this._tone({ type: 'triangle', f0: 880, dur: 0.2, vol: 0.16, delay: 0.18 });
  };
  AudioEngine.prototype.death = function () {
    this._noise({ dur: 0.4, vol: 0.28, freq: 900 });
    this._tone({ type: 'sawtooth', f0: 420, f1: 60, slide: 0.35, dur: 0.4, vol: 0.2 });
  };
  AudioEngine.prototype.zap = function () {
    this._noise({ dur: 0.08, vol: 0.12, freq: 2500 });
  };
  AudioEngine.prototype.click = function () {
    this._tone({ type: 'square', f0: 880, dur: 0.05, vol: 0.10 });
  };
  AudioEngine.prototype.win = function () {
    var self = this;
    [523, 659, 784, 1047, 1319].forEach(function (f, i) {
      self._tone({ type: 'triangle', f0: f, dur: 0.28, vol: 0.18, delay: i * 0.11 });
    });
  };
  AudioEngine.prototype.complete = function () {
    var self = this;
    [392, 523, 659, 784, 1047, 784, 1047, 1319].forEach(function (f, i) {
      self._tone({ type: 'triangle', f0: f, dur: 0.3, vol: 0.16, delay: i * 0.13 });
    });
  };

  /* ----- Music: 16-step loop over a 4-chord loop ----- */
  var CHORDS = [
    [45, 48, 52],   // A minor
    [41, 45, 48],   // F major
    [48, 52, 55],   // C major
    [43, 47, 50]    // G major
  ];
  var ARP = [0, 1, 2, 1, 0, 2, 1, 2];

  function mtof(m) { return 440 * Math.pow(2, (m - 69) / 12); }

  AudioEngine.prototype._schedule = function () {
    if (!this.ctx || !this.enabled || !this.musicOn) return;
    var stepDur = 60 / this.bpm / 4; // 16th notes
    while (this._nextTime < this.ctx.currentTime + 0.25) {
      var s = this._step % 16;
      var chord = CHORDS[Math.floor(this._step / 16) % 4];
      var t0 = this._nextTime;
      // arp lead
      if (s % 2 === 0) {
        var note = chord[ARP[(s / 2) % 8] % 3] + 24;
        this._tone({ type: 'triangle', f0: mtof(note), dur: 0.12, vol: 0.05, delay: t0 - this.ctx.currentTime, music: true });
        // move _tone to absolute time instead:
      }
      // bass
      if (s % 8 === 0) {
        this._tone({ type: 'sawtooth', f0: mtof(chord[0] - 12), dur: 0.34, vol: 0.07, delay: t0 - this.ctx.currentTime, music: true });
      }
      // hat
      if (s % 4 === 2) {
        this._tone({ type: 'square', f0: 6000, dur: 0.03, vol: 0.012, delay: t0 - this.ctx.currentTime, music: true });
      }
      this._step++;
      this._nextTime += stepDur;
    }
  };

  AudioEngine.prototype.startMusic = function () {
    if (!this._ensure() || this._musicTimer) return;
    this._nextTime = this.ctx.currentTime + 0.1;
    var self = this;
    this._musicTimer = setInterval(function () { self._schedule(); }, 80);
  };

  AudioEngine.prototype.stopMusic = function () {
    if (this._musicTimer) { clearInterval(this._musicTimer); this._musicTimer = null; }
  };

  AudioEngine.prototype.setMusic = function (on) {
    this.musicOn = on;
    if (on) this.startMusic(); else this.stopMusic();
  };

  root.GBAudio = new AudioEngine();
})(typeof globalThis !== 'undefined' ? globalThis : this);

/* ============================================================
   GRAVITY BREAK — particle system
   Simple pooled particle list with additive rendering.
   ============================================================ */
(function (root) {
  'use strict';

  var MAX = 700;

  function Particles() {
    this.list = [];
  }

  Particles.prototype.spawn = function (x, y, vx, vy, life, color, size, opts) {
    if (this.list.length >= MAX) this.list.shift();
    opts = opts || {};
    this.list.push({
      x: x, y: y, vx: vx, vy: vy,
      life: life, maxLife: life,
      color: color, size: size,
      g: opts.g !== undefined ? opts.g : 0,
      drag: opts.drag !== undefined ? opts.drag : 0,
      fade: opts.fade !== false,
      shrink: opts.shrink !== false,
      square: !!opts.square
    });
  };

  Particles.prototype.burst = function (x, y, n, color, speed, opts) {
    opts = opts || {};
    for (var i = 0; i < n; i++) {
      var a = Math.random() * Math.PI * 2;
      var s = speed * (0.3 + Math.random() * 0.7);
      this.spawn(
        x, y,
        Math.cos(a) * s, Math.sin(a) * s,
        (opts.life || 0.5) * (0.5 + Math.random() * 0.8),
        color,
        (opts.size || 3) * (0.5 + Math.random() * 0.8),
        { g: opts.g, drag: opts.drag, square: opts.square }
      );
    }
  };

  Particles.prototype.update = function (dt) {
    for (var i = this.list.length - 1; i >= 0; i--) {
      var p = this.list[i];
      p.life -= dt;
      if (p.life <= 0) { this.list.splice(i, 1); continue; }
      p.vy += p.g * dt;
      if (p.drag) { var d = 1 - p.drag * dt; p.vx *= d; p.vy *= d; }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
  };

  Particles.prototype.draw = function (ctx, ox, oy) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (var i = 0; i < this.list.length; i++) {
      var p = this.list[i];
      var t = p.life / p.maxLife;
      ctx.globalAlpha = p.fade ? t : 1;
      ctx.fillStyle = p.color;
      var s = p.shrink ? p.size * (0.35 + 0.65 * t) : p.size;
      var x = p.x - ox, y = p.y - oy;
      if (p.square) {
        ctx.fillRect(x - s / 2, y - s / 2, s, s);
      } else {
        ctx.beginPath();
        ctx.arc(x, y, s / 2, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
  };

  Particles.prototype.clear = function () { this.list.length = 0; };

  root.GBParticles = Particles;
})(typeof globalThis !== 'undefined' ? globalThis : this);

/* ============================================================
   GRAVITY BREAK — entities & physics
   Player controller (AABB vs tile-grid + moving platforms),
   and moving platform update. Dependency-free.
   ============================================================ */
(function (root) {
  'use strict';

  var TILE = 32;
  var P = {
    W: 20, H: 30,
    MAX_SPEED: 330,
    ACCEL_GROUND: 2600,
    ACCEL_AIR: 1500,
    DECEL_GROUND: 2900,
    DECEL_AIR: 200,
    GRAVITY: 1500,
    MAX_FALL: 950,
    JUMP_V: 565,
    JUMP_CUT: 0.42,
    COYOTE: 0.1,
    BUFFER: 0.13
  };

  /* ---------- Moving platform ---------- */
  function Platform(def) {
    this.id = def.id;
    this.baseX = def.tx * TILE;
    this.baseY = def.ty * TILE;
    this.x = this.baseX; this.y = this.baseY;
    this.w = def.w; this.h = def.h;
    this.axis = def.axis;
    this.travel = def.travel;
    this.speed = def.speed;
    this.dir = 1;
    this.dx = 0; this.dy = 0;
  }

  Platform.prototype.rect = function () {
    return { x: this.x, y: this.y, w: this.w, h: this.h };
  };

  Platform.prototype.update = function (dt) {
    var px = this.x, py = this.y;
    var max = this.travel;
    if (this.axis === 'x') {
      this.x += this.speed * this.dir * dt;
      if (this.x > this.baseX + max) { this.x = this.baseX + max; this.dir = -1; }
      if (this.x < this.baseX) { this.x = this.baseX; this.dir = 1; }
      this.dx = this.x - px; this.dy = 0;
    } else {
      this.y += this.speed * this.dir * dt;
      if (this.y > this.baseY + max) { this.y = this.baseY + max; this.dir = -1; }
      if (this.y < this.baseY) { this.y = this.baseY; this.dir = 1; }
      this.dx = 0; this.dy = this.y - py;
    }
  };

  /* ---------- Player ---------- */
  function Player(startX, startY) {
    this.w = P.W; this.h = P.H;
    this.reset(startX, startY, 1);
  }

  Player.prototype.reset = function (x, y, gdir) {
    this.x = x - this.w / 2;
    this.y = y - this.h;
    this.vx = 0; this.vy = 0;
    this.gdir = gdir;                 // 1 = down, -1 = up
    this.grounded = false;
