/* ============================================================
   GRAVITY BREAK — stylesheet
   ============================================================ */
:root {
  --accent: #00e5ff;
  --accent2: #ff2d78;
  --bg: #04050f;
  --panel: rgba(10, 14, 34, 0.92);
  --font-display: 'Orbitron', 'Segoe UI', system-ui, sans-serif;
  --font-body: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { height: 100%; overflow: hidden; }
body {
  background:
    radial-gradient(1200px 600px at 50% -10%, rgba(0, 229, 255, 0.07), transparent 60%),
    radial-gradient(1000px 500px at 50% 110%, rgba(255, 45, 120, 0.06), transparent 60%),
    var(--bg);
  font-family: var(--font-body);
  color: #dfeaff;
  -webkit-user-select: none;
  user-select: none;
  touch-action: manipulation;
}
#app { height: 100%; display: flex; align-items: center; justify-content: center; }

/* stage keeps the 1024x544 canvas aspect on any screen */
#stage {
  position: relative;
  width: min(100vw, calc(100vh * (1024 / 544) - 0px));
  height: min(100vh, calc(100vw * (544 / 1024)));
  background: #000;
  box-shadow: 0 0 40px rgba(0, 229, 255, 0.18), 0 0 120px rgba(255, 45, 120, 0.08);
  overflow: hidden;
}
@media (aspect-ratio: 1024/544) { #stage { width: 100vw; height: 100vh; } }

#game { display: block; width: 100%; height: 100%; background: #04050f; }

/* ---------- HUD ---------- */
#hud {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; justify-content: space-between; align-items: center;
  padding: 10px 16px;
  font-family: var(--font-display);
  font-size: clamp(10px, 1.6vmin, 15px);
  letter-spacing: 0.12em;
  pointer-events: none;
  text-shadow: 0 0 8px rgba(0, 229, 255, 0.5);
  z-index: 5;
}
#hud-left { color: #9fc6ff; display: flex; gap: 12px; align-items: baseline; }
#hud-level { color: var(--accent); font-weight: 700; }
#hud-name { color: #7d90b5; font-size: 0.85em; }
#hud-mid { color: #8ffcff; font-weight: 700; }
#hud-mid .shard-icon { color: var(--accent); margin-right: 6px; text-shadow: 0 0 10px var(--accent); }
#hud-right { color: #9fc6ff; display: flex; gap: 14px; }
#hud-deaths { color: #ff85ad; }

.icon-btn {
  position: absolute; top: 8px; right: 10px;
  width: 38px; height: 38px; border-radius: 10px;
  background: rgba(10, 16, 40, 0.7);
  border: 1px solid rgba(0, 229, 255, 0.35);
