}
.icon-btn:hover { border-color: var(--accent); box-shadow: 0 0 14px rgba(0, 229, 255, 0.4); }

/* level banner */
#level-banner {
  position: absolute; top: 22%; left: 0; right: 0;
  text-align: center;
  font-family: var(--font-display);
  font-weight: 900;
