#touch .tc-left { position: absolute; left: 12px; bottom: calc(12px + env(safe-area-inset-bottom)); display: flex; gap: 10px; }
#touch .tc-right { position: absolute; right: 12px; bottom: calc(12px + env(safe-area-inset-bottom)); display: flex; gap: 10px; }
