}
h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(18px, 4.5vmin, 40px);
  letter-spacing: 0.22em;
  color: #fff;
  text-shadow: 0 0 14px rgba(0, 229, 255, 0.7);
}
.tagline {
  font-family: var(--font-display);
  font-size: clamp(9px, 1.9vmin, 15px);
  letter-spacing: 0.42em;
  color: #79c9ff;
