}
.footer-hint { color: #46598a; font-size: clamp(8px, 1.5vmin, 12px); letter-spacing: 0.2em; }

.menu-col { display: flex; flex-direction: column; gap: 1.4vmin; align-items: center; }

.btn {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(11px, 2.3vmin, 18px);
  letter-spacing: 0.22em;
  color: #d5ecff;
  background: linear-gradient(180deg, rgba(20, 30, 66, 0.9), rgba(10, 15, 36, 0.9));
