  box-shadow: 0 0 22px rgba(255, 45, 120, 0.25);
}
.btn-primary:hover { border-color: var(--accent2); box-shadow: 0 0 26px rgba(255, 45, 120, 0.55), inset 0 0 18px rgba(255, 45, 120, 0.14); }
