/* level select */
#level-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.6vmin;
  width: min(92%, 900px);
}
.level-cell {
  position: relative;
  display: flex; flex-direction: column; gap: 0.6vmin; align-items: center; justify-content: center;
  min-height: clamp(56px, 12vmin, 110px);
  background: linear-gradient(180deg, rgba(16, 22, 48, 0.9), rgba(8, 11, 28, 0.9));
  border: 1.5px solid color-mix(in srgb, var(--accent, #00e5ff) 45%, transparent);
  border-radius: 12px;
  color: #dfeaff; cursor: pointer;
  font-family: var(--font-display);
  transition: all 0.15s ease;
  padding: 1vmin;
}
.level-cell:hover:not(.locked) {
  transform: translateY(-2px);
