  function standFloorQuar2(x, r) { return standFloor(x, r); }

  var nodes = [];
  var seen = {};
  function key(n) { return n[0] + ',' + n[1] + ',' + n[2]; }
  function pushNode(x, r, t) {
    var k = key([x, r, t]);
    if (!seen[k]) { seen[k] = true; nodes.push([x, r, t]); return true; }
