var LV = require('../js/levels.js');
var T = LV.TILE;

function moverFloors(L) {
  var map = {};
  L.movers.forEach(function (m) {
    if (m.axis === 'x') {
      var x0 = m.tx, x1 = Math.floor((m.tx * T + m.travel) / T);
      for (var x = x0; x <= x1 + 2; x++) map[x + ',' + m.ty] = true;
    } else {
      var y0 = m.ty, y1 = m.ty + Math.round(m.travel / T);
      for (var y = y0; y <= y1; y++) for (var x = m.tx; x <= m.tx + 2; x++) map[x + ',' + y] = true;
    }
  });
  return map;
}

var L = LV.compile(LV.LEVELS[0], 0);
var mf = moverFloors(L);
function g(x, y) { if (x < 0 || y < 0 || x >= L.w || y >= L.h) return 1; return L.grid[y * L.w + x]; }
var solid = function (x, y) { return g(x, y) === 1; };
var standSolid = function (x, y) { return solid(x, y) || mf[x + ',' + y] === true; };
var empty = function (x, y) { return g(x, y) === 0; };

function standFloor(x, r) {
  if (r < 2 || r >= L.h) return false;
  return standSolid(x, r) && empty(x, r - 1) && empty(x, r - 2);
}

console.log('standFloor(2,15)', standFloor(2, 15));
console.log('standFloor(4,15)', standFloor(4, 15));

// manual BFS count
var seen = {}, nodes = [];
function push(x, r, t) { var k = x + ',' + r + ',' + t; if (!seen[k]) { seen[k] = 1; nodes.push([x, r, t]); } }
for (var r = 15; r <= 21; r++) if (standFloor(2, r)) { push(2, r, 'f'); break; }
console.log('seed', nodes);

var guard = 0;
while (nodes.length && guard++ < 100000) {
  var n = nodes.pop();
  var x = n[0], r = n[1], t = n[2];
  var isFloor = t === 'f';
  function standAt(xx, rr) { return isFloor ? standFloor(xx, rr) : false; }
  [1, -1].forEach(function (d) {
    var xx = x + d;
    if (xx < 0 || xx >= L.w) return;
    if (standAt(xx, r)) push(xx, r, t);
  });
}
console.log('walk-only nodes:', nodes.length, 'max x:', Math.max.apply(null, nodes.map(function(n){return n[0];})));

