var LV = require('../js/levels.js');
var T = LV.TILE;

function reach(L, shardTx, shardTy) {
  function mf(L) {
    var map = {};
    L.movers.forEach(function (m) {
      if (m.axis === 'x') {
        var x0 = m.tx, x1 = Math.floor((m.tx * T + m.travel) / T);
        for (var x = x0; x <= x1 + 2; x++) map[x + ',' + m.ty] = true;
      } else {
        var y1 = m.ty + Math.round(m.travel / T);
        for (var y = m.ty; y <= y1; y++) for (var x = m.tx; x <= m.tx + 2; x++) map[x + ',' + y] = true;
      }
    });
    return map;
  }
  var m = mf(L);
  function g(x, y) { if (x < 0 || y < 0 || x >= L.w || y >= L.h) return 1; return L.grid[y * L.w + x]; }
  function solid(x, y) { return g(x, y) === 1; }
  function standSolid(x, y) { return solid(x, y) || m[x + ',' + y] === true; }
  function empty(x, y) { return g(x, y) === 0; }
  function standFloor(x, r) { return r >= 2 && r < L.h && standSolid(x, r) && empty(x, r - 1) && empty(x, r - 2); }
  function standCeil(x, r) { return r >= 1 && r < L.h && solid(x, r) && empty(x, r + 1) && empty(x, r + 2); }
  function floorDrop(x, fromRow) {
    for (var r = Math.max(2, fromRow); r < L.h; r++) if (standSolid(x, r) && standFloor(x, r)) return r;
    return -1;
  }
  var nodes = [], visited = [], seen = {};
  function push(x, r, t) { var k = x + ',' + r + ',' + t; if (!seen[k]) { seen[k] = 1; visited.push([x, r, t]); nodes.push([x, r, t]); } }
  for (var r = L.start.ty + 1; r <= L.start.ty + 7; r++) if (standFloor(L.start.tx, r)) { push(L.start.tx, r, 'f'); break; }
  var reachBase = [7, 6, 4, 3], guard = 0;
  while (nodes.length && guard++ < 200000) {
    var n = nodes.pop(), x = n[0], r = n[1], t = n[2], isFloor = t === 'f';
