      else { var fr2 = floorDrop(xx, r + 3); if (fr2 > 0 && fr2 - r <= 17) push(xx, fr2, 'f'); }
    });
    if (isFloor) {
      for (var dUp = 0; dUp <= 3; dUp++) {
        var clearH = true;
        for (var i = 1; i <= dUp + 1; i++) if (!empty(x, r - 1 - i)) { clearH = false; break; }
        if (!clearH) continue;
        var base = reachBase[dUp];
        for (var dx = -base; dx <= base; dx++) {
          var xt = x + dx;
          if (xt < 0 || xt >= L.w || dx === 0) continue;
          for (var rL = r - 1 - dUp; rL <= r + 6; rL++) {
            if (standFloor(xt, rL)) {
              var dDown = rL - r, reach = dDown > dUp ? base + Math.min(3, dDown - dUp) : base;
              if (Math.abs(dx) <= reach) { push(xt, rL, 'f'); break; }
            }
          }
        }
      }
      var rsF = -1;
      for (var r2 = r - 1; r2 >= 0 && r2 >= r - 17; r2--) {
        if (solid(x, r2)) { rsF = r2; break; }
        if (!empty(x, r2)) { rsF = -1; break; }
      }
      if (rsF >= 0 && standCeil(x, rsF)) push(x, rsF, 'c');
