var VAL = (function () {
  // quick probe for L2 shard 30,13 using same BFS as validate.js
  var LV = require('../js/levels.js');
  var T = LV.TILE;
  var L = LV.compile(LV.LEVELS[1], 1);
  var acc = (function () {
    function g(x, y) { if (x < 0 || y < 0 || x >= L.w || y >= L.h) return 1; return L.grid[y * L.w + x]; }
    return { g: g, solid: function (x, y) { return g(x, y) === 1; }, empty: function (x, y) { return g(x, y) === 0; } };
  })();
  function standFloor(x, r) { return r >= 2 && r < L.h && acc.solid(x, r) && acc.empty(x, r - 1) && acc.empty(x, r - 2); }
  function standCeil(x, r) { return r >= 0 && r < L.h && acc.solid(x, r) && acc.empty(x, r + 1) && acc.empty(x, r + 2); }
  function floorDrop(x, fromRow) {
    for (var r = Math.max(2, fromRow); r < L.h; r++) if (acc.solid(x, r) && standFloor(x, r)) return r;
    return -1;
  }
  var nodes = [], visited = [], seen = {};
  function push(x, r, t) { var k = x + ',' + r + ',' + t; if (!seen[k]) { seen[k] = 1; visited.push([x, r, t]); nodes.push([x, r, t]); } }
  for (var r0 = L.start.ty + 1; r0 <= L.start.ty + 7; r0++) if (standFloor(L.start.tx, r0)) { push(L.start.tx, r0, 'f'); break; }
  var reachBase = [7, 6, 4, 3], guard = 0;
  while (nodes.length && guard++ < 200000) {
    var n = nodes.pop(), x = n[0], r = n[1], t = n[2], isFloor = t === 'f';
    function standAt(xx, rr) { return isFloor ? standFloor(xx, rr) : standCeil(xx, rr); }
    [1, -1].forEach(function (d) {
      var xx = x + d;
      if (xx < 0 || xx >= L.w) return;
      if (standAt(xx, r)) push(xx, r, t);
      else if (isFloor) { var fr = floorDrop(xx, r + 1); if (fr > 0 && fr - r <= 16) push(xx, fr, 'f'); }
      else { var fr2 = floorDrop(xx, r + 3); if (fr2 > 0 && fr2 - r <= 17) push(xx, fr2, 'f'); }
    });
    if (isFloor) {
      for (var dUp = 0; dUp <= 3; dUp++) {
        var clearH = true;
        for (var i = 1; i <= dUp + 1; i++) if (!acc.empty(x, r - 1 - i)) { clearH = false; break; }
        if (!clearH) continue;
        var base = reachBase[dUp];
        for (var dx = -base; dx <= base; dx++) {
          var xt = x + dx;
          if (xt < 0 || xt >= L.w || dx === 0) continue;
          for (var rL = r - 1 - dUp; rL <= r + 6; rL++) {
            if (standFloor(xt, rL)) {
              var dDown = rL - r, reach = dDown > dUp ? base + Math.min(3, dDown - dUp) : base;
              if (Math.abs(dx) <= reach) { push(xt, rL, 'f'); break; }
            }
          }
        }
      }
      var rsF = -1;
      for (var r2 = r - 1; r2 >= 0 && r2 >= r - 17; r2--) {
        if (acc.solid(x, r2)) { rsF = r2; break; }
        if (!acc.empty(x, r2)) { rsF = -1; break; }
      }
      if (rsF >= 0 && standCeil(x, rsF)) push(x, rsF, 'c');
    } else {
      var rb = -1;
      for (var r3 = r + 1; r3 <= Math.min(L.h - 1, r + 17); r3++) {
        if (acc.solid(x, r3)) { rb = r3; break; }
        if (!acc.empty(x, r3)) { rb = -1; break; }
      }
      if (rb > 0 && standFloor(x, rb)) push(x, rb, 'f');
    }
  }
  console.log('visited', visited.length);
  [25, 32, 33].forEach(function (c) {
    console.log('node ' + c + ',15?', visited.some(function (n) { return n[0] === c && n[1] === 15 && n[2] === 'f'; }));
  });
  var shard = { tx: 30, ty: 13 };
  var hits = visited.filter(function (n) {
    var isFloor = n[2] === 'f';
    var bodyRows = isFloor ? [n[1] - 1, n[1] - 2] : [n[1] + 1, n[1] + 2];
    if (bodyRows.indexOf(shard.ty) >= 0) return n[0] === shard.tx;
    var win = [];
    for (var i = -5; i <= -1; i++) win.push(n[1] + (isFloor ? i : -i));
    return win.indexOf(shard.ty) >= 0 && Math.abs(n[0] - shard.tx) <= 4;
  });
  console.log('shard hits:', JSON.stringify(hits));
})();

